package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.util.*;
final class LibraryOverview {
 static void render(Context c,LinearLayout parent,JSONArray items,boolean media){int done=0,platinum=0,playing=0,backlog=0;double hours=0;Map<String,Integer> years=new TreeMap<>(),months=new TreeMap<>(),genres=new HashMap<>(),platforms=new HashMap<>(),ratings=new HashMap<>();for(int i=0;i<items.length();i++){JSONObject x=items.optJSONObject(i);String status=x.optString("status"),group=LibraryStatus.group(status,media);if(LibraryStatus.finished(status,media)){done++;String date=x.optString("data");if(date.matches("[12][0-9]{3}-[0-9]{2}-[0-9]{2}.*")){add(years,date.substring(0,4));add(months,date.substring(0,7));}}if(group.equals("Platinados"))platinum++;if(group.equals("Em progresso")||group.equals("Jogando agora")||group.equals("Assistindo"))playing++;if(group.equals("Backlog")||group.equals("Para assistir"))backlog++;double h=x.optDouble("horas",0);if(!Double.isNaN(h)&&!Double.isInfinite(h)&&h>0)hours+=h;for(String p:x.optString(media?"onde":"plataforma","").split("[,|]"))add(platforms,p.trim());String rating=x.optString("nota","");add(ratings,rating);Object gs=x.opt("generos");if(gs instanceof JSONArray){JSONArray a=(JSONArray)gs;Set<String> seen=new HashSet<>();for(int k=0;k<a.length();k++)if(seen.add(a.optString(k)))add(genres,a.optString(k));}else if(gs instanceof String)for(String g:((String)gs).split("[,|]"))add(genres,g.trim());}
  LinearLayout stats=panel(c,parent);stats.addView(NativeSheet.text(c,media?"🎬 Seu acervo de histórias":"🎮 Sua biblioteca gamer",17,0xfff3effa));String[] labels=media?new String[]{"🎞️ Títulos","✅ Assistidos","▶️ Assistindo","🍿 Para assistir"}:new String[]{"🕹️ Jogos","🏁 Finalizados","💎 Platinados","⏱️ Horas jogadas"};String[] values=media?new String[]{""+items.length(),""+done,""+playing,""+backlog}:new String[]{""+items.length(),""+done,""+platinum,Math.round(hours)+"h"};for(int r=0;r<2;r++){LinearLayout row=new LinearLayout(c);stats.addView(row);for(int col=0;col<2;col++){int index=r*2+col;LinearLayout tile=new LinearLayout(c);tile.setOrientation(LinearLayout.VERTICAL);tile.setPadding(NativeSheet.dp(c,12),NativeSheet.dp(c,8),NativeSheet.dp(c,12),NativeSheet.dp(c,8));int[] accents={0xffb59bff,0xff7bdfab,0xff6ed8ef,0xffffc476};int accent=accents[index];android.graphics.drawable.GradientDrawable glow=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{(accent&0xffffff)|0x33000000,0xff201c2e});glow.setCornerRadius(NativeSheet.dp(c,14));glow.setStroke(NativeSheet.dp(c,1),(accent&0xffffff)|0x55000000);tile.setBackground(glow);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(0,NativeSheet.dp(c,4),col==0?NativeSheet.dp(c,8):0,NativeSheet.dp(c,4));row.addView(tile,tp);tile.addView(NativeSheet.text(c,labels[index],11,0xffafa0c2));TextView count=NativeSheet.text(c,values[index],24,accent);count.setTypeface(null,android.graphics.Typeface.BOLD);tile.addView(count);}}
  Button charts=new Button(c);charts.setText("Estatísticas da biblioteca ▾");AppStyle.button(charts,false);parent.addView(charts);LinearLayout details=new LinearLayout(c);details.setOrientation(LinearLayout.VERTICAL);details.setVisibility(android.view.View.GONE);parent.addView(details);charts.setOnClickListener(v->{boolean open=details.getVisibility()!=android.view.View.VISIBLE;details.setVisibility(open?android.view.View.VISIBLE:android.view.View.GONE);charts.setText(open?"Estatísticas da biblioteca ▴":"Estatísticas da biblioteca ▾");});bars(c,details,media?"Assistidos por ano":"Finalizados por ano",years,0xff91b877,12);
  Map<String,Integer> recent=new LinkedHashMap<>();Calendar calendar=Calendar.getInstance(TimeZone.getTimeZone("America/Sao_Paulo"));calendar.set(Calendar.DAY_OF_MONTH,1);calendar.add(Calendar.MONTH,-11);for(int i=0;i<12;i++){String key=String.format(Locale.ROOT,"%04d-%02d",calendar.get(Calendar.YEAR),calendar.get(Calendar.MONTH)+1);recent.put(key,months.containsKey(key)?months.get(key):0);calendar.add(Calendar.MONTH,1);}bars(c,details,media?"Assistidos nos últimos 12 meses":"Finalizados nos últimos 12 meses",recent,0xff91b877,12);bars(c,details,"Gêneros mais frequentes",genres,0xffffb570,7);bars(c,details,media?"Onde assistir":"Plataformas",platforms,0xffa889f4,7);bars(c,details,"Avaliações",ratings,0xffffd96e,9);
 }
 static void rank(Context c,LinearLayout parent){LinearLayout panel=panel(c,parent);LinearLayout head=new LinearLayout(c);head.setGravity(android.view.Gravity.CENTER_VERTICAL);head.addView(NativeSheet.text(c,"🏆 Ranking dos CLTs",17,0xffffd38a),new LinearLayout.LayoutParams(0,-2,1));Button open=new Button(c);open.setText("Ver todos ›");AppStyle.button(open,false);open.setTextSize(11);open.setMinWidth(0);open.setPadding(NativeSheet.dp(c,8),0,NativeSheet.dp(c,8),0);head.addView(open,new LinearLayout.LayoutParams(NativeSheet.dp(c,100),NativeSheet.dp(c,44)));open.setEnabled(false);panel.addView(head);TextView state=NativeSheet.text(c,"Carregando classificação…",11,0xffad9cbb);panel.addView(state);LinearLayout list=new LinearLayout(c);list.setOrientation(LinearLayout.VERTICAL);panel.addView(list);new AccountRepository(c).ranking((rows,error)->{if(error!=null){state.setText(error);return;}String user=SessionPreferences.get(c).getString("user_id","");for(int i=0;i<rows.length();i++){JSONObject me=rows.optJSONObject(i);if(user.equals(me.optString("id"))){state.setText("Você: #"+(i+1)+" • Nível "+ProfileProgress.level(me.optLong("xp"))+" • "+me.optLong("xp")+" XP");break;}}rankingRows(c,list,rows,3);open.setEnabled(true);open.setOnClickListener(v->{NativeSheet sheet=new NativeSheet(c,"Ranking dos CLTs");rankingRows(c,sheet.body,rows,rows.length());sheet.show();});});}
 private static void rankingRows(Context c,LinearLayout list,JSONArray rows,int limit){list.removeAllViews();String own=SessionPreferences.get(c).getString("user_id","");for(int i=0;i<Math.min(limit,rows.length());i++){JSONObject p=rows.optJSONObject(i);long xp=p.optLong("xp");int level=ProfileProgress.level(xp);LinearLayout row=new LinearLayout(c);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(NativeSheet.dp(c,8),NativeSheet.dp(c,6),NativeSheet.dp(c,8),NativeSheet.dp(c,6));boolean mine=own.equals(p.optString("id"));row.setBackground(AppStyle.shape(row,mine?0xff33243d:0x331d1a2c,12));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(0,NativeSheet.dp(c,3),0,NativeSheet.dp(c,3));list.addView(row,rp);TextView place=NativeSheet.text(c,i<3?new String[]{"🥇","🥈","🥉"}[i]:"#"+(i+1),17,0xffffc979);row.addView(place,new LinearLayout.LayoutParams(NativeSheet.dp(c,32),-2));ImageView avatar=new ImageView(c);avatar.setImageResource(R.drawable.app_logo);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(AppStyle.shape(avatar,0xff332a44,18));avatar.setClipToOutline(true);row.addView(avatar,new LinearLayout.LayoutParams(NativeSheet.dp(c,34),NativeSheet.dp(c,34)));AccountImageLoader.load(avatar,p.optString("avatar_url"));LinearLayout copy=new LinearLayout(c);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(NativeSheet.dp(c,9),0,NativeSheet.dp(c,4),0);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView name=NativeSheet.text(c,p.optString("nome","CLT")+(mine?" • Você":""),13,0xfff1e8ff);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(0,0,0,0);copy.addView(name);TextView sub=NativeSheet.text(c,ProfileProgress.title(level)+" • Nível "+level,10,0xffb8a6ce);sub.setPadding(0,NativeSheet.dp(c,2),0,0);copy.addView(sub);row.addView(NativeSheet.text(c,xp+" XP",11,i<3?0xffffd089:0xffbda7df));}}
 private static void add(Map<String,Integer> map,String key){if(key.isEmpty()||key.equals("null"))return;map.put(key,map.containsKey(key)?map.get(key)+1:1);}
 private static void bars(Context c,LinearLayout parent,String title,Map<String,Integer> data,int color,int limit){LinearLayout box=panel(c,parent);box.addView(NativeSheet.text(c,title,17,0xfff2e9fc));if(data.isEmpty()){box.addView(NativeSheet.text(c,"Sem dados cadastrados para este resumo.",12,0xffa69abc));return;}List<Map.Entry<String,Integer>> rows=new ArrayList<>(data.entrySet());if(!(data instanceof LinkedHashMap)&&!(data instanceof TreeMap))Collections.sort(rows,(a,b)->Integer.compare(b.getValue(),a.getValue()));int maximum=1;for(Map.Entry<String,Integer> row:rows)maximum=Math.max(maximum,row.getValue());for(int i=0;i<Math.min(limit,rows.size());i++){Map.Entry<String,Integer> row=rows.get(i);LinearLayout label=new LinearLayout(c);box.addView(label);TextView name=NativeSheet.text(c,row.getKey(),12,0xffbfb2cf);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);label.addView(name,new LinearLayout.LayoutParams(0,-2,1));label.addView(NativeSheet.text(c,String.valueOf(row.getValue()),12,0xfff3edf9));ProgressBar bar=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(maximum);bar.setProgress(row.getValue());bar.setProgressTintList(android.content.res.ColorStateList.valueOf(color));box.addView(bar,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,6)));}}
 private static LinearLayout panel(Context c,LinearLayout parent){LinearLayout box=new LinearLayout(c);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(NativeSheet.dp(c,12),NativeSheet.dp(c,10),NativeSheet.dp(c,12),NativeSheet.dp(c,10));box.setBackground(AppStyle.shape(box,0xee17131f,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,12,0,16);parent.addView(box,lp);return box;}
}
